interface StripAvoidProps {
  product?: ShopifyProduct;
}

export default function StripAvoid({ product }: StripAvoidProps) {
  const hardcodedItems: AvoidItem[] = [
    {
      title: "Pregnant or breastfeeding individuals",
      formattedTitle: (
        <>
          Pregnant or
          <br />
          breastfeeding individuals
        </>
      ),
      icon: ICONS.pregnant,
      delay: 0,
    },
    {
      title: "Individuals under 16",
      icon: ICONS.child,
      delay: 0.05,
    },
    {
      title: "Anyone allergic to mushrooms",
      formattedTitle: (
        <>
          Anyone allergic to
          <br />
          mushrooms
        </>
      ),
      icon: ICONS.allergy,
      delay: 0.1,
    },
    {
      title: "Those with medical conditions (consult a professional)",
      formattedTitle: (
        <>
          Those with medical
          <br />
          conditions (consult a professional)
        </>
      ),
      icon: ICONS.medical,
      delay: 0.15,
    },
  ];

  const items = useMemo(() => {
    // cardWithIcon is now a mapped object containing icon_cards (array of objects)
    const list = product?.cardWithIcon?.icon_cards || product?.cardWithIcon?.icon_card;
    if (!list || !Array.isArray(list) || list.length === 0) return hardcodedItems;

    return list.map((node: any, i: number) => {
      const fallback = hardcodedItems[i % hardcodedItems.length];
      const title = node.text || "";
      
      let icon = fallback.icon;
      if (node.icon && typeof node.icon === 'string') {
        icon = <img src={node.icon} alt={title} className="w-[82px] h-[82px] object-contain" />;
      } else if (node.icon_symbol) {
        icon = node.icon_symbol === 'pregnant' ? ICONS.pregnant :
               node.icon_symbol === 'child' ? ICONS.child :
               node.icon_symbol === 'allergy' ? ICONS.allergy :
               node.icon_symbol === 'medical' ? ICONS.medical :
               fallback.icon;
      }

      return {
        title: title,
        formattedTitle: <span dangerouslySetInnerHTML={{
          __html: title.split(' ').reduce((acc: string, word: string, idx: number, arr: string[]) => {
            if (idx === Math.floor(arr.length / 2)) return acc + '<br />' + word;
            return acc + ' ' + word;
          }, '')
        }} />,
        icon: icon,
        delay: i * 0.05,
      } as AvoidItem;
    });
  }, [product]);

  const sectionRef = useRef<HTMLDivElement | null>(null);
  const [isDesktop, setIsDesktop] = useState(false);

  useEffect(() => {
    const handleResize = () => setIsDesktop(window.innerWidth >= 1024);
    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const { scrollYProgress } = useScroll({ target: sectionRef, offset: ["start start", "end end"] });
  const oddParallax = useSpring(useTransform(scrollYProgress, [0, 1], [30, -30]), {
    stiffness: 120,
    damping: 20,
    mass: 0.4,
  });

  const evenParallax = useSpring(useTransform(scrollYProgress, [0, 1], [-30, 30]), {
    stiffness: 120,
    damping: 20,
    mass: 0.4,
  });

  return (
    <section
      ref={sectionRef}
      className="avoid-wrapper relative overflow-hidden bg-[linear-gradient(180deg,transparent_0%,var(--product-background-color)_51.44%,transparent_100%)] py-[50px] lg:py-28"
    >

      <div className="relative container mx-auto space-y-12 xl:space-y-[98px]">
        <div className="max-w-2xl">
          <h2
            className="text-[clamp(42px,_5vw,_76px)] leading-[1.05] text-[#000] dark:text-black font-semibold max-lg:text-center"
            dangerouslySetInnerHTML={{ __html: product?.cardWithIcon?.title || "Who Should<br />Avoid It" }}
          />
        </div>

        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
          {items.map((item, idx) => (
            <motion.div
              key={item.title}
              className="relative lg:h-[375px] flex flex-col justify-between gap-[80px] rounded-[10px] bg-StripPrimary text-white dark:text-white dark:*:text-white px-6 py-7"
              style={isDesktop ? { y: idx % 2 === 0 ? evenParallax : oddParallax } : undefined}
              initial={{ opacity: 0, scale: 0.98 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true, amount: 0.5 }}
              transition={{ duration: 0.55, ease: [0.22, 1, 0.36, 1], delay: item.delay }}
              whileHover={{ scale: 1.02 }}
            >
              <div className="h-[82px] flex items-center justify-start">{item.icon}</div>
              <p className="text-[16px] leading-[1.5] pr-2">{item.formattedTitle ?? item.title}</p>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
